/* ---------- Engine 13: risks ---------- */
function risks(ctx,M){
  var L={L:1,M:2,H:3},LN={L:'Low',M:'Medium',H:'High'};
  function test(w){
    if(w==='ambiguous')return ctx.ambiguous;
    if(w.indexOf('completeness<')===0)return ctx.completeness<parseFloat(w.split('<')[1]);
    if(w.indexOf('approvalDays>')===0)return ctx.waitDays>parseFloat(w.split('>')[1]);
    if(w.indexOf('domain:')===0)return ctx.domains.indexOf(w.slice(7))>-1;
    if(w.indexOf('activity:')===0)return ctx.actIds.indexOf(w.slice(9))>-1;
    if(w==='unknownInfra')return (ctx.domains.indexOf('cloud')>-1||ctx.domains.indexOf('infra')>-1)&&!ctx.pre.has('aws')&&!ctx.pre.has('azure')&&!ctx.pre.has('gcp')&&!ctx.pre.has('on premise');
    if(w==='has:integrations')return ctx.pre.integrations.filter(function(i){return !/AWS|Azure|Google Cloud|WhatsApp|Mainframe/.test(i)}).length>0||ctx.hasInteg;
    if(w==='has:inferred')return ctx.inferred>0;
    if(w==='has:capability_gap')return ctx.gaps>0;
    if(w==='has:deadline')return ctx.deadline;
    if(w==='has:specialist')return ctx.specialist;
    return false;
  }
  return M.risks.filter(function(r){return test(r.when)}).map(function(r){
    var s=L[r.p]*L[r.i];
    return {risk_id:r.id,description:r.desc,probability:LN[r.p],impact:LN[r.i],severity:s>=6?'High':s>=3?'Medium':'Low',_s:s,mitigation:r.mitigation,responsible_role:r.owner};
  }).sort(function(a,b){return b._s-a._s}).map(function(r){delete r._s;return r});
}

/* ---------- output validation ---------- */
var SCHEMA={project:{title:'s',problem_statement:'s',primary_category:'s',proposed_solution:'s',complexity:'s',estimated_duration:'o',confidence_score:'n'},
  solution:{summary:'s',components:'a',technical_requirements:'a',integrations:'a'},agents:'a',phases:'a',
  resources:{human_roles:'a',agent_roles:'a',human_effort_hours:'n',agent_effort_hours:'n'},
  automation:{coverage_percentage:'n',autonomous_effort_percentage:'n',supervised_effort_percentage:'n',human_led_effort_percentage:'n'},
  delivery:{critical_path:'a',milestones:'a',risks:'a',assumptions:'a'},business_impact:{expected_outcomes:'a',measurable_metrics:'a'}};
