    if(!o.phases.length)errs.push('no phases');
    o.phases.forEach(function(p){if(!(p.end_week>=p.start_week))errs.push('phase '+p.phase_id+' has invalid weeks');if(!p.deliverables.length)errs.push('phase '+p.phase_id+' has no deliverables')});
